// Each lane covers 2 channels (stride 32), then a warp shuffle tree reduces to lane 0.
__global__ void __launch_bounds__(512, 4) min_tanh_tanh_kernel_warp(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int HW
